Relevant lines update without celebration.\\\",\\r\\n      \\\"object\\\": null,\\r\\n      \\\"order_key\\\": null,\\r\\n      \\\"authority\\\": \\\"proposed\\\",\\r\\n      \\\"canon\\\": false\\r\\n    },\\r\\n    {\\r\\n      \\\"record_id\\\": \\\"rec-w6c6d736915186b6955123a55\\\",\\r\\n      \\\"subject\\\": \\\"owen\\\",\\r\\n      \\\"predicate\\\": \\\"entity_role\\\",\\r\\n      \\\"value\\\": \\\"protagonist\\\",\\r\\n      \\\"object\\\": null,\\r\\n      \\\"order_key\\\": null,\\r\\n      \\\"authority\\\": \\\"proposed\\\",\\r\\n      \\\"canon\\\": false\\r\\n    },\\r\\n    {\\r\\n      \\\"record_id\\\": \\\"rec-w81c9d2bef32375fc63201a3c\\\",\\r\\n      \\\"subject\\\": \\\"load_share\\\",\\r\\n      \\\"predicate\\\": \\\"manifests_as\\\",\\r\\n      \\\"value\\\": \\\"Weight spreads across connected lines rather than bearing on a single line. This is a separate permission, never an extra function of ranked Threadline.\\\",\\r\\n      \\\"object\\\": null,\\r\\n      \\\"order_key\\\": null,\\r\\n      \\\"authority\\\": \\\"proposed\\\",\\r\\n      \\\"canon\\\": false\\r\\n    },\\r\\n    {\\r\\n      \\\"record_id\\\": \\\"rec-w8bfe775df0657e0a453c85b9\\\",\\r\\n      \\\"subject\\\": \\\"slot_rank\\\",\\r\\n      \\\"predicate\\\": \\\"manifests_as\\\",\\r\\n      \\\"value\\\": \\\"The Slot Rank line displays the person's counted standing; under the same load, stronger installed abilities can become steadier and last longer.\\\",\\r\\n      \\\"object\\\": null,\\r\\n      \\\"order_key\\\": null,\\r\\n      \\\"authority\\\": \\\"proposed\\\",\\r\\n      \\\"canon\\\": false\\r\\n    },\\r\\n    {\\r\\n      \\\"record_id\\\": \\\"rec-w918e5e186a992bf8bb1eb58d\\\",\\r\\n      \\\"subject\\\": \\\"load_share\\\",\\r\\n      \\\"predicate\\\": \\\"is_a\\\",\\r\\n      \\\"value\\\": \\\"Load Share\\\",\\r\\n      \\\"object\\\": null,\\r\\n      \\\"order_key\\\": null,\\r\\n      \\\"authority\\\": \\\"proposed\\\",\\r\\n      \\\"canon\\\":